<template><div class="page-title"><div><h2>知识库与设备资料</h2><p>检索现行规程、设备台账、应急预案和维修记录</p></div><el-button type="primary" plain>导入资料</el-button></div><div class="panel"><div class="filterbar" style="padding:16px 18px 0"><el-input placeholder="搜索规程、设备或异常处理方法" style="max-width:430px"/><el-select placeholder="资料状态" style="width:130px"><el-option label="现行" value="current"/><el-option label="待审" value="pending"/></el-select><el-button type="primary">检索</el-button></div><div class="table-wrap"><el-table :data="[{title:'二泵站运行规程',type:'运行规程',version:'v1.2',scope:'二泵站',status:'现行',date:'2026-08-12'},{title:'泵组异常处理预案',type:'应急预案',version:'v0.9',scope:'全工程',status:'待审',date:'2026-10-01'},{title:'四泵站 2 号泵维修手册',type:'设备手册',version:'v2.1',scope:'四泵站',status:'废止',date:'2025-12-18'}]"><el-table-column prop="title" label="资料名称"/><el-table-column prop="type" label="类型"/><el-table-column prop="version" label="版本"/><el-table-column prop="scope" label="适用范围"/><el-table-column prop="date" label="有效时间"/><el-table-column prop="status" label="状态"><template #default="s"><span :class="['tag',s.row.status==='现行'?'tag-green':s.row.status==='待审'?'tag-amber':'tag-red']">{{s.row.status}}</span></template></el-table-column><el-table-column label="操作"><template #default><el-button link type="primary">预览引用</el-button></template></el-table-column></el-table></div></div></template>
